#include<bits/stdc++.h>using namespace std;const int maxn=2e5+10;long long t,n,a[maxn],now[maxn],sum[maxn];int main()/////////////{    cin>>t;    while(t--)    {        cin>>n;        for(int i=1;i<=n;i++)        {            sum[i]=0,now[i]=0;        }        for(int i=1;i<=n;i++)        {            cin>>a[i];            sum[i]=sum[i-1]+a[i];            now[i]=max(now[i-1],a[i]);        }        for(int i=1;i<=n;i++)        {            if(a[n-i+1]<now[n-i])            {                cout<<sum[n]-sum[n-i]+now[n-i]-a[n-i+1]<<" ";            }            else            cout<<sum[n]-sum[n-i]<<" ";        }        cout<<endl;    }}